	('8cb95223-1e33-4d3b-b35c-7c19083991d0', '3fca3112-91d5-4e05-a2bb-126685fb3011', 'crear_admin', 'usuarios', '3a6aadf4-32fe-4914-ad53-87b04d019e4b', NULL, '{"correo": "yarvishazmeunhuevo@gmail.com", "nivel_admin": "admin"}', '::1', '2026-06-20 21:10:06.722226+00'),
	('fde39000-8d68-405a-aa9b-587dd056a149', '3fca3112-91d5-4e05-a2bb-126685fb3011', 'reactivar_admin', 'usuarios', '3a6aadf4-32fe-4914-ad53-87b04d019e4b', NULL, '{"is_active": true, "estado_cuenta": "activa"}', NULL, '2026-06-21 01:15:42.413076+00'),
	('4a8b3782-8e40-4740-9008-f4873de0ad9f', '72e9950c-4520-47b5-9c3b-ef947c237a76', 'editar_descripcion_proyecto', 'proyectos', '9cabc18b-898f-4c3f-95b2-4641acc055d9', '{"descripcion": "Problema y contexto: La clínica dental gestiona actualmente las reservas de turnos mediante llamadas telefónicas y mensajes de WhatsApp. Este método genera desorganización, riesgo de duplicar citas y consume mucho tiempo del personal para coordinar horarios, lo que afecta la eficiencia operativa y la experiencia del paciente.\nObjetivo y alcance: El proyecto debe permitir a los pacientes consultar disponibilidad de horarios y reservar turnos a través de una interfaz web y una aplicación móvil. Al confirmarse una reserva, el sistema enviará una notificación inmediata al personal de la clínica. Además, enviará recordatorios automáticos de citas a los pacientes, gestionará el calendario interno, mantendrá un historial básico de pacientes (nombre, contacto y citas anteriores) y ofrecerá la posibilidad de cancelar o reprogramar turnos. El alcance incluye la creación de los módulos de gestión de agenda, notificaciones, historial de pacientes y una capa de acceso móvil, pero excluye la integración con sistemas de facturación o software dental externo."}', '{"descripcion": "Problema y contexto: La clínica dental gestiona actualmente las reservas de turnos mediante llamadas telefónicas y mensajes de WhatsApp. Este método genera desorganización, riesgo de duplicar citas y consume mucho tiempo del personal para coordinar horarios, lo que afecta la eficiencia operativa y la experiencia del paciente, mediante un rating de 1-5 estrellas.\nObjetivo y alcance: El proyecto debe permitir a los pacientes consultar disponibilidad de horarios y reservar turnos a través de una interfaz web y una aplicación móvil. Al confirmarse una reserva, el sistema enviará una notificación inmediata al personal de la clínica. Además, enviará recordatorios automáticos de citas a los pacientes, gestionará el calendario interno, mantendrá un historial básico de pacientes (nombre, contacto y citas anteriores) y ofrecerá la posibilidad de cancelar o reprogramar turnos. El alcance incluye la creación de los módulos de gestión de agenda, notificaciones, historial de pacientes y una capa de acceso móvil, pero excluye la integración con sistemas de facturación o software dental externo."}', NULL, '2026-06-23 05:05:49.987041+00'),
	('a8eb885b-dacb-446a-9688-ed9112b92485', '72e9950c-4520-47b5-9c3b-ef947c237a76', 'editar_descripcion_proyecto', 'proyectos', '9cabc18b-898f-4c3f-95b2-4641acc055d9', '{"descripcion": "Problema y contexto: La clínica dental gestiona actualmente las reservas de turnos mediante llamadas telefónicas y mensajes de WhatsApp. Este método genera desorganización, riesgo de duplicar citas y consume mucho tiempo del personal para coordinar horarios, lo que afecta la eficiencia operativa y la experiencia del paciente, mediante un rating de 1-5 estrellas.\nObjetivo y alcance: El proyecto debe permitir a los pacientes consultar disponibilidad de horarios y reservar turnos a través de una interfaz web y una aplicación móvil. Al confirmarse una reserva, el sistema enviará una notificación inmediata al personal de la clínica. Además, enviará recordatorios automáticos de citas a los pacientes, gestionará el calendario interno, mantendrá un historial básico de pacientes (nombre, contacto y citas anteriores) y ofrecerá la posibilidad de cancelar o reprogramar turnos. El alcance incluye la creación de los módulos de gestión de agenda, notificaciones, historial de pacientes y una capa de acceso móvil, pero excluye la integración con sistemas de facturación o software dental externo."}', '{"descripcion": "Problema y contexto: La clínica dental gestiona actualmente las reservas de turnos mediante llamadas telefónicas y mensajes de WhatsApp. Este método genera desorganización, riesgo de duplicar citas y consume mucho tiempo del personal para coordinar horarios, lo que afecta la eficiencia operativa y la experiencia del paciente, mediante un rating de 1-5 estrellas.\nObjetivo y alcance: El proyecto debe permitir a los pacientes consultar disponibilidad de horarios y reservar turnos a través de una interfaz web y una aplicación móvil. Al confirmarse una reserva, el sistema enviará una notificación inmediata al personal de la clínica, mediante sus correos. Además, enviará recordatorios automáticos de citas a los pacientes, gestionará el calendario interno, mantendrá un historial básico de pacientes (nombre, contacto y citas anteriores) y ofrecerá la posibilidad de cancelar o reprogramar turnos. El alcance incluye la creación de los módulos de gestión de agenda, notificaciones, historial de pacientes y una capa de acceso móvil, pero excluye la integración con sistemas de facturación o software dental externo."}', NULL, '2026-06-23 05:08:53.097203+00');


