INSERT INTO "public"."proyectos" ("id_proyecto", "id_empresario", "id_area_negocio", "titulo", "descripcion", "involucra_ia", "presupuesto_min", "presupuesto_max", "moneda", "modalidad", "pais_iso_proyecto", "region_proyecto", "estado", "motivo_cancelacion", "fecha_publicacion", "fecha_cierre", "postulaciones_pendientes_revisar", "is_active", "created_at", "updated_at", "generado_por_ia") VALUES
	('9a53bc7a-1136-4a09-81b4-2e5b2a46ab6f', 'd66e446f-94b7-47d6-9728-1ec09601673b', '2ac58ff1-9da4-4f96-9eaa-777beeac0cb7', 'Sistema de Contabilidad y Facturación para PyME', 'Problema y contexto: El contador gestiona la contabilidad y la facturación de sus clientes PyME mediante hojas de cálculo y herramientas separadas, lo que genera duplicidad de información, errores manuales y pérdida de tiempo. Esta situación afecta la precisión de los registros contables y retrasa la entrega de facturas a los clientes, impactando la confianza y la eficiencia del negocio.
Objetivo y alcance: El sistema debe permitir el registro de asientos contables, la gestión de clientes, la generación de facturas, el control de ingresos y gastos, la elaboración de reportes financieros y una conciliación bancaria básica sin conexión directa a entidades bancarias. Se incluyen módulos para crear y editar asientos, mantener un catálogo de clientes, emitir facturas en formato PDF, registrar movimientos de ingresos y egresos, y generar reportes de balance, resultados y flujo de efectivo. No se contemplan integraciones con bancos ni la gestión de nómina en esta fase.
Supuestos y exclusiones: Se asume que los usuarios disponen de conocimientos básicos de contabilidad pero no técnicos; el cobro y la gestión de nómina quedan fuera del alcance y no se integrarán con sistemas bancarios externos.', false, 100000.00, 400000.00, 'CRC', 'remoto', NULL, NULL, 'abierto', NULL, '2026-06-18 00:00:00+00', '2026-06-26 00:00:00+00', 0, true, '2026-06-18 03:33:17.006171+00', '2026-06-21 21:48:53.049043+00', true),
	('fff9a023-e468-49d7-917b-7e9ff25da75a', 'd66e446f-94b7-47d6-9728-1ec09601673b', '0e95ee6c-3cda-46f7-af85-71921b964fd7', 'Plataforma SaaS de gestión de churn para empresas de suscripción', 'Problema y contexto: Las empresas SaaS con modelo de suscripción recurrente pierden ingresos significativos por la cancelación de suscripciones (churn). Actualmente no disponen de una herramienta centralizada que identifique de forma rápida a los clientes con alta probabilidad de cancelar, lo que dificulta la toma de decisiones proactivas y afecta la retención y el crecimiento del negocio.
Objetivo y alcance: Desarrollar una aplicación web de una única cuenta que permita la gestión de usuarios internos, muestre un dashboard con métricas clave de suscripciones (usuarios activos, ingresos mensuales, tasa de churn) actualizado de forma periódica, y ofrezca una predicción básica de churn mediante un modelo pre‑entrenado o reglas estáticas. El sistema generará alertas dentro de la propia aplicación cuando el riesgo de churn supere un umbral definido y presentará informes simples en pantalla. No se incluirá soporte multi‑tenant, actualizaciones en tiempo real, envío de correos electrónicos, integraciones avanzadas, campañas de marketing automatizadas ni aplicaciones móviles.
Supuestos y exclusiones: Se asume que la información de suscriptores (fecha de alta, uso, pagos) ya está disponible en una base de datos relacional; el procesamiento de pagos y el envío de correos quedan fuera del alcance, al igual que cualquier integración con sistemas externos avanzados.', true, 200.00, 800.00, 'USD', 'remoto', NULL, NULL, 'abierto', NULL, '2026-06-17 00:00:00+00', '2026-06-29 00:00:00+00', 0, true, '2026-06-17 22:01:26.827236+00', '2026-06-21 21:48:53.049043+00', true),
	('9cabc18b-898f-4c3f-95b2-4641acc055d9', 'd66e446f-94b7-47d6-9728-1ec09601673b', '29676bfc-0d48-40b3-8bf3-47ff6f8e4d12', 'Sistema de reservas online para clínica dental', 'Problema y contexto: La clínica dental gestiona actualmente las reservas de turnos mediante llamadas telefónicas y mensajes de WhatsApp. Este método genera desorganización, riesgo de duplicar citas y consume mucho tiempo del personal para coordinar horarios, lo que afecta la eficiencia operativa y la experiencia del paciente, mediante un rating de 1-5 estrellas.
Objetivo y alcance: El proyecto debe permitir a los pacientes consultar disponibilidad de horarios y reservar turnos a través de una interfaz web y una aplicación móvil. Al confirmarse una reserva, el sistema enviará una notificación inmediata al personal de la clínica, mediante sus correos. Además, enviará recordatorios automáticos de citas a los pacientes, gestionará el calendario interno, mantendrá un historial básico de pacientes (nombre, contacto y citas anteriores) y ofrecerá la posibilidad de cancelar o reprogramar turnos. El alcance incluye la creación de los módulos de gestión de agenda, notificaciones, historial de pacientes y una capa de acceso móvil, pero excluye la integración con sistemas de facturación o software dental externo.', false, 600.00, 690.00, 'USD', 'remoto', NULL, NULL, 'abierto', NULL, '2026-06-16 00:00:00+00', '2026-06-24 00:00:00+00', 1, true, '2026-06-16 17:37:20.010921+00', '2026-06-23 08:00:00.179726+00', true),
	('ae368a8a-21d9-4501-9553-4234e41066bd', 'd66e446f-94b7-47d6-9728-1ec09601673b', '5a0f71eb-8d7b-4a2f-ad54-c6a99c68eb3d', 'API Backend para Gestión de Inventario de Joyería', 'Desarrollo de una API RESTful en Node.js/Express con PostgreSQL para manejar CRUD de productos, autenticación con JWT y notificaciones a Slack cuando el stock sea menor a 10 unidades. Incluye documentación OpenAPI, scripts Docker, pruebas automatizadas y configuración CI/CD.', false, 200.00, 400.00, 'USD', 'remoto', NULL, NULL, 'abierto', NULL, '2026-06-15 00:00:00+00', '2026-06-20 00:00:00+00', 0, true, '2026-06-15 06:18:29.941238+00', '2026-06-22 20:32:17.132356+00', true),
	('098cfee8-e62e-40ee-9518-a43bc43119ee', 'fb546260-2e90-4954-944c-594b35461017', '5a0f71eb-8d7b-4a2f-ad54-c6a99c68eb3d', 'Desarrollo de backend para pagina de empresa de repuestos', 'Problema y contexto:
La empresa vende repuestos de automóviles y actualmente gestiona el catálogo, inventario y pedidos de forma manual, lo que genera demoras en la búsqueda de piezas, errores de disponibilidad y un proceso de compra lento. Los clientes deben contactar por teléfono o visitar la tienda física, y el personal debe registrar ventas en papel, lo que dificulta el control de stock y la generación de reportes. Con un presupuesto de 1000‑2000 USD, un plazo de 8 días y la necesidad de operar en USD desde San José, Costa Rica, se busca una solución digital que permita a los clientes buscar repuestos por marca, modelo, año y categoría, ver disponibilidad en tiempo real y comprar de forma rápida con tarjetas, transferencias o efectivo.
Objetivo y alcance:
El sistema debe ofrecer un portal web donde los usuarios puedan registrarse, iniciar sesión y gestionar su perfil, buscar y filtrar productos según los criterios indicados, añadirlos al carrito, aplicar descuentos y completar la compra mediante una pasarela que acepte tarjetas, transferencias y registro de pagos en efectivo, reduciendo el tiempo de checkout. Además, debe incluir gestión de usuarios y roles (cliente, administrador, empleado de ventas), CRUD de productos, categorías, marcas y proveedores, control de inventario con actualizaciones automáticas al confirmar una venta, y generación de reportes básicos de ventas e inventario. El alcance queda limitado a estas funcionalidades; no se incluirá integración con sistemas contables externos ni gestión de envíos internacionales.
Supuestos y exclusiones:
Se asume que los pagos en efectivo se registrarán manualmente en el sistema y que la pasarela de pago se configurará con Stripe Checkout aunque no se detalla su integración. Quedan fuera del alcance la integración con WhatsApp, la automatización de envíos y la generación de reportes avanzados personalizados.', false, 1000.00, 2000.00, 'USD', 'remoto', '', NULL, 'abierto', NULL, '2026-06-18 00:00:00+00', '2026-06-26 00:00:00+00', 0, true, '2026-06-18 19:55:28.1812+00', '2026-06-22 20:31:27.547397+00', true),
	('7ecd2037-ac15-43e9-8d85-3be09d06fa74', 'db6671a4-770b-448c-8b4b-731d7a401613', '159531c8-fefd-4fa5-b435-76bea788b6b7', 'sistema para  publicar alitas de pollo', 'Problema y contexto:
El negocio vende alitas de pollo fritas a través de redes sociales, lo que limita el alcance a potenciales clientes y obliga a gestionar pedidos de forma manual. Actualmente no hay un sitio donde se muestren los precios de los productos ni se pueda registrar un apartado, y el pago se realiza al momento de la entrega mediante Sinpe móvil. Además, la venta está disponible solo de lunes a viernes, lo que requiere controlar la disponibilidad de los pedidos.
Objetivo y alcance:
Desarrollar una aplicación web que permita al administrador publicar las alitas con su descripción y precio, y que los clientes puedan navegar el catálogo, seleccionar la cantidad deseada y crear un apartado indicando la fecha de entrega dentro del rango de lunes a viernes. El sistema enviará una confirmación al cliente y registrará la reserva en una base de datos para su posterior gestión. No se integrará ningún pasarela de pago; el cobro se realizará manualmente al entregar el pedido. La plataforma será responsiva y contará con un panel de administración para crear, editar y eliminar productos, así como para visualizar las reservas realizadas.
Supuestos y exclusiones:
Se asume que el pago será cobrado manualmente mediante Sinpe móvil al entregar el pedido, por lo que el sistema no incluye integración con pasarelas de pago. No se gestionará la logística de entrega ni se integrará con las redes sociales existentes. Las reservas solo podrán generarse para días hábiles de lunes a viernes; los fines de semana quedan fuera del alcance.', false, 10000.00, 50000.00, 'USD', 'remoto', NULL, NULL, 'adjudicado', NULL, '2026-06-16 00:00:00+00', '2026-06-28 00:00:00+00', 0, true, '2026-06-16 20:27:54.069781+00', '2026-06-22 20:31:43.483029+00', true),
	('337cdc05-98d4-49b1-98aa-1bfabd942d11', 'd66e446f-94b7-47d6-9728-1ec09601673b', '5a0f71eb-8d7b-4a2f-ad54-c6a99c68eb3d', 'Gestión de cartas del mundial', 'Problema y contexto: La empresa vende cartas del álbum PANINI Mundial 2026 a coleccionistas de todo el mundo y actualmente enfrenta una alta dificultad para controlar el inventario, ya que la gestión se realiza de forma manual y sin una herramienta centralizada, lo que genera pérdidas y retrasos en la disponibilidad de productos.
Objetivo y alcance: Desarrollar una aplicación web que permita a los coleccionistas navegar un catálogo de cartas, añadir productos a un carrito de compras, realizar el pago con tarjetas de crédito/débito y confirmar la compra. El sistema debe actualizar el stock en tiempo real, ofrecer al administrador reportes de ventas por período, productos más vendidos y nivel de inventario, y contar con una interfaz responsiva. Quedan fuera del alcance la gestión de envíos internacionales y la atención al cliente fuera del portal.
Supuestos y exclusiones: Se asume que los pagos se procesarán mediante una pasarela de tarjetas integrada y que la gestión de envíos se realizará fuera del sistema; no se incluirán otros métodos de pago ni módulos de atención al cliente.', false, 1500.00, 2500.00, 'USD', 'remoto', NULL, NULL, 'en_desarrollo', NULL, '2026-06-18 00:00:00+00', '2026-06-28 00:00:00+00', 0, true, '2026-06-18 20:39:25.891571+00', '2026-06-22 20:38:07.647171+00', true),
	('c28c4dc9-e60a-4f60-9566-c8c2e0e2102f', 'd66e446f-94b7-47d6-9728-1ec09601673b', 'f7b10e42-2bb6-4068-b663-1ab4ec1993cd', 'Sistema de reservas online para cancha de fútbol 5', 'Problema y contexto: El negocio consiste en una cancha de fútbol 5 ubicada en San José, Costa Rica, que actualmente recibe reservas por teléfono. Esta modalidad genera solapamiento de horarios porque a veces se pisan dos reservas, lo que genera confusión y pérdida de tiempo tanto para los clientes como para el administrador. El cliente necesita una forma sencilla y rápida de consultar los horarios libres y apartar un espacio sin depender de llamadas.
Objetivo y alcance: El sistema debe permitir a cualquier usuario visualizar en tiempo real los horarios disponibles de la cancha y seleccionar el bloque de tiempo que desea reservar, generando una confirmación visual de la reserva. El alcance incluye una interfaz web pública para la consulta y reserva, y un panel de administración donde el propietario pueda ver, editar o cancelar reservas manualmente. No se incluyen funcionalidades de pago en línea, envío de notificaciones, integración con terceros ni control de acceso; el proceso de pago y la comunicación posterior se gestionan fuera del sistema.
Supuestos y exclusiones: Se asume que el propietario manejará los pagos y las notificaciones por sus propios medios y que el sistema no requerirá integraciones con otros canales o sistemas. No se implementarán controles de acceso ni mensajería dentro del producto.', false, 300000.00, 1500000.00, 'USD', 'presencial', 'CR', 'CR-SJ', 'abierto', NULL, '2026-06-23 00:00:00+00', '2026-06-29 00:00:00+00', 0, true, '2026-06-23 00:42:18.180992+00', '2026-06-23 00:42:18.180992+00', true),
	('d922c543-2cbc-425e-82d9-331cfecd7997', 'd66e446f-94b7-47d6-9728-1ec09601673b', '0e95ee6c-3cda-46f7-af85-71921b964fd7', 'Plataforma de streaming indie – MVP con apps móviles y recomendaciones IA', 'Problema y contexto: El cliente quiere ofrecer una plataforma de streaming enfocada en cine independiente para usuarios que buscan series y películas de nicho. Actualmente esos contenidos son difíciles de encontrar en servicios masivos y el cliente busca una solución que permita a los usuarios registrarse, explorar un catálogo y reproducir videos, con la visión de escalar a millones de usuarios y contar con una CDN propia y recomendaciones basadas en IA. El público objetivo son amantes del cine independiente que buscan una experiencia de visualización sencilla y personalizada.
Objetivo y alcance: El sistema debe permitir el registro de usuarios, la navegación por un catálogo de títulos y la reproducción de video en la web y en aplicaciones móviles nativas para iOS y Android. Además incluirá un motor de recomendaciones básico que utilice técnicas de IA para sugerir contenidos según el historial de visualización. El alcance incluye una aplicación web desarrollada con React, una API backend con Node.js que gestione usuarios, catálogos y streaming, una base de datos PostgreSQL para almacenar la información y una aplicación móvil multiplataforma con Flutter para iOS y Android. Se utilizará un CDN externo para la entrega de los videos durante el MVP. No se incluye la implementación de una CDN propia, la arquitectura para soportar millones de usuarios concurrentes ni un motor de recomendaciones avanzado.
Supuestos y exclusiones: Se asume que el cliente proveerá los archivos de video y los metadatos del catálogo, y que gestionará los derechos de contenido. Quedan fuera del alcance la infraestructura de CDN propia, la escalabilidad a nivel de millones de usuarios simultáneos y un algoritmo de recomendación avanzado; estos se planificarán en fases posteriores.', true, 2000.00, 5000.00, 'USD', 'remoto', NULL, NULL, 'abierto', NULL, '2026-06-23 00:00:00+00', '2026-07-03 00:00:00+00', 0, true, '2026-06-23 01:34:19.549006+00', '2026-06-23 01:34:19.549006+00', true),
	('efebd922-1cec-4111-b1c0-c1bc75d64029', 'd66e446f-94b7-47d6-9728-1ec09601673b', '159531c8-fefd-4fa5-b435-76bea788b6b7', 'Sistema de toma de órdenes y cálculo de vuelto para soda', 'Problema y contexto: El negocio es una soda en San José, Costa Rica, que atiende a clientes de forma presencial y solo acepta pagos en efectivo en colones costarricenses. Actualmente los cajeros suman mentalmente el total de la orden y calculan el vuelto, lo que genera errores frecuentes y demoras en el servicio, afectando la satisfacción de los clientes y la confianza en el establecimiento.
Objetivo y alcance: El sistema debe permitir al cajero registrar rápidamente los ítems de la orden, calcular automáticamente el subtotal, el total a pagar y, al ingresar el monto entregado por el cliente, mostrar el vuelto exacto en colones. Incluirá una pantalla de captura de productos, cálculo automático de totales y una vista de historial simple de ventas para consultas posteriores. No se incluirá gestión de inventario, pagos con tarjeta ni integración con sistemas externos.
Supuestos y exclusiones: Se asume que todas las transacciones serán en efectivo y que el negocio proveerá la lista de precios de los productos. Se excluye cualquier funcionalidad de inventario, pagos electrónicos y generación de reportes avanzados, tal como indicó el empresario.', false, 100000.00, 20000000.00, 'CRC', 'presencial', 'CR', 'CR-SJ', 'abierto', NULL, '2026-06-23 00:00:00+00', '2026-07-03 00:00:00+00', 0, true, '2026-06-23 03:01:24.63114+00', '2026-06-23 03:01:24.63114+00', true),
	('603a0eb2-2b54-4d18-bdc6-6797e1f61e5c', 'd66e446f-94b7-47d6-9728-1ec09601673b', '5a0f71eb-8d7b-4a2f-ad54-c6a99c68eb3d', 'Sitio web para Sabor Casero con menú y reservas', 'Problema y contexto: El restaurante Sabor Casero en San José recibe reservas por teléfono y WhatsApp, lo que genera llamadas perdidas, reservas duplicadas y dificultades para organizar horarios en momentos de alta demanda. Además, no dispone de una presencia online donde los clientes puedan ver el menú con fotos y precios.
Objetivo y alcance: Desarrollar una página web que muestre el menú completo con imágenes y precios y que incluya un formulario de reserva online. El formulario debe capturar nombre, teléfono, correo electrónico, fecha, hora, cantidad de personas y comentarios adicionales, y enviar la información a un backend que la almacene en una base de datos. El sitio será estático para el menú y tendrá una sección de reservas con validación básica. No se implementarán pagos en línea, gestión automática de mesas ni envío de recordatorios.
Supuestos y exclusiones: Se asume que el cliente gestionará la asignación de mesas manualmente y que los pagos se harán en el restaurante; el envío de recordatorios automáticos y la integración con WhatsApp quedan fuera del alcance.', false, 100.00, 2000.00, 'USD', 'remoto', NULL, NULL, 'adjudicado', NULL, '2026-06-18 00:00:00+00', '2026-06-23 00:00:00+00', 0, true, '2026-06-18 21:46:42.259612+00', '2026-06-23 04:25:24.246991+00', true),
	('e089390c-7834-41eb-a384-55d0e182d475', 'd66e446f-94b7-47d6-9728-1ec09601673b', 'f7b10e42-2bb6-4068-b663-1ab4ec1993cd', 'Gym Class Booking and Attendance Web App', 'Problem and context: The gym currently relies on phone calls, texts, and a handwritten notebook to manage class bookings and attendance, which leads to missed appointments and disorganized records. The owner wants a digital solution that lets members independently reserve spots in classes and view their own attendance history, improving accuracy and convenience. The project will be delivered remotely, priced in USD, with a budget of $500–$1500 and an 8‑day timeline.
Objective and scope: The system must provide a responsive web application where members can register, log in, browse a schedule of upcoming classes, book a class, and view a personal log of attended sessions. An administrative interface will allow staff to create and edit class offerings. The MVP will not include payment processing, class cancellations, wait‑lists, reminders, or notification features.
Assumptions and exclusions: It is assumed that staff will manually record attendance in the system after each class. Payment integration, cancellation handling, wait‑list management, and automated reminders are explicitly out of scope for this version.', false, 500.00, 1500.00, 'USD', 'remoto', NULL, NULL, 'abierto', NULL, '2026-06-23 00:00:00+00', '2026-07-01 00:00:00+00', 1, true, '2026-06-23 02:35:29.544409+00', '2026-06-30 00:00:00.167414+00', true),
	('4e11dfe9-d4eb-481f-b17e-c92260ccd4f7', 'd66e446f-94b7-47d6-9728-1ec09601673b', 'f7b10e42-2bb6-4068-b663-1ab4ec1993cd', 'Sistema de Vuelos de mercancía de Mariscos', 'Problema/contexto: La empresa exporta mariscos de Costa Rica a Francia y necesita que sus clientes franceses, operarios, administradores y recibidores puedan seguir en tiempo real cada envío, verificar lotes, consultar horarios de vuelos y subir comprobantes de transferencia. Actualmente la información está dispersa y no hay una herramienta centralizada, lo que genera incertidumbre y retrasos. 
Objetivo y alcance: Desarrollar un portal web mínimo viable que permita a los usuarios visualizar el tracking de los pedidos, generar reportes de lotes, recibir alertas de horarios y cargar comprobantes de pago. 
Qué incluye: • Frontend web responsivo con autenticación (Firebase Auth) para los cuatro tipos de usuarios. • Dashboard de tracking con mapa y estado del envío en tiempo real (datos simulados o API interna). • Sección de reportes de lotes descargables en PDF/CSV. • Sistema de alertas por email o notificación dentro del portal para horarios críticos. • Formulario para subir comprobantes de transferencia (almacenamiento en Firebase Storage). • Backend API (Node.js + Express) que expone endpoints para consultar tracking, lotes y recibir archivos. • Despliegue en Vercel con configuración sencilla. 
Qué queda fuera de alcance: Gestión de pagos, funcionalidades de marketing, integración con CI/CD avanzado, Docker y pipelines de automatización.', false, 1000.00, 1000.00, 'USD', 'remoto', NULL, NULL, 'en_desarrollo', NULL, '2026-06-15 00:00:00+00', '2026-06-30 00:00:00+00', 0, true, '2026-06-15 16:51:53.287004+00', '2026-06-23 04:47:20.600875+00', true),
	('1e8759fd-bd46-49e2-a57e-9668fecc8b18', '257600b6-585a-4502-af52-f9973372cfd1', '5a0f71eb-8d7b-4a2f-ad54-c6a99c68eb3d', 'Sitio web promocional y tienda online para joyería', 'Problema y contexto: El negocio de joyería se dirige principalmente a mujeres entre 17 y 45 años y actualmente solo se promociona a través de redes sociales, sin contar con una presencia digital propia. La falta de un sitio web impide mostrar el catálogo completo, recibir consultas formales y ofrecer la opción de compra online, lo que limita la captación de clientes y la generación de ventas directas.
Objetivo y alcance: Desarrollar una página web responsiva que incluya un catálogo visual de los productos, un formulario de contacto para consultas y un flujo de compra que permita al cliente registrar su pedido y recibir instrucciones para efectuar la transferencia bancaria. El sitio debe permitir al administrador actualizar el catálogo y consultar los pedidos recibidos. No se incluirá integración con pasarelas de pago ni funcionalidades de gestión de inventario avanzado.
Supuestos y exclusiones: Se asume que el pago se realizará exclusivamente por transferencia bancaria y que la confirmación del mismo será manual; el proyecto no contempla integración con sistemas de pago electrónico ni desarrollo de una aplicación móvil.', false, 800.00, 1000.00, 'USD', 'remoto', NULL, NULL, 'finalizado', NULL, '2026-06-21 00:00:00+00', '2026-07-06 00:00:00+00', 0, true, '2026-06-21 05:08:07.459199+00', '2026-06-23 07:34:46.633977+00', true),
	('29fc8ed7-0223-44e3-8b9d-44d2c2b3b04b', '257600b6-585a-4502-af52-f9973372cfd1', '5a0f71eb-8d7b-4a2f-ad54-c6a99c68eb3d', 'Desarrollo de gestión de sistema automatizado para inventario de bodega', 'Problema y contexto: La tienda de ropa gestiona el inventario manualmente, lo que genera lentitud e inconsistencias en la cantidad real de prendas. Los administradores de la bodega son los usuarios que deben registrar, editar y eliminar los ítems. La falta de información actualizada afecta la reposición y la satisfacción del cliente.
Objetivo y alcance: El sistema debe permitir a los administradores crear, modificar y borrar registros de inventario de diferentes tipos de prendas, consultar el stock disponible, generar reportes de movimientos y emitir alertas cuando el nivel de stock sea inferior al umbral definido. El alcance incluye módulos de gestión de productos, historial de cambios, generación de reportes tabulares y notificaciones por correo electrónico de stock bajo. No se incluyen integraciones con sistemas de punto de venta ni gestión de ventas.
Supuestos y exclusiones: Se asume que el inventario se manejará en una única ubicación física y que los usuarios dispondrán de acceso a un navegador web. Se excluye la integración con sistemas externos de pagos o de e‑commerce, tal como indicó el empresario.', false, 1000.00, 1500.00, 'USD', 'hibrido', 'DE', 'DE-BW', 'abierto', NULL, '2026-06-23 00:00:00+00', '2026-07-08 00:00:00+00', 0, true, '2026-06-23 21:13:56.711228+00', '2026-06-23 21:13:56.711228+00', true),
	('7a609303-9470-42ca-aa57-54a4a1e16d33', '257600b6-585a-4502-af52-f9973372cfd1', '5a0f71eb-8d7b-4a2f-ad54-c6a99c68eb3d', 'Desarrollo de plataforma web profesional con diseño responsive', 'Problema y contexto: La empresa del sector comercial actualmente depende de redes sociales y mensajería para presentar su catálogo, lo que limita la capacidad de ofrecer información completa y estructurada, dificulta la generación de consultas y reduce la confianza de los clientes al no contar con un sitio propio.
Objetivo y alcance: Desarrollar una plataforma web moderna, responsiva y profesional que sirva como vitrina digital del catálogo de productos y servicios. El sistema mostrará una página de inicio, una sección de catálogo con filtrado por categorías, páginas de detalle de cada producto con imágenes, descripción, características y precio, y un formulario de contacto para que los usuarios envíen consultas. La arquitectura será basada en Next.js con React y Tailwind CSS para garantizar un diseño adaptable a computadoras, tablets y móviles, y los datos del catálogo se almacenarán en una base PostgreSQL accesible mediante una API sencilla. No se implementará carrito de compra, pasarela de pagos ni gestión de usuarios.
Supuestos y exclusiones: Se asume que el cliente proveerá todo el contenido del catálogo (imágenes, textos, precios y categorías) y que la publicación del sitio se realizará en un hosting estático. Quedan fuera del alcance la integración de pagos, la creación de cuentas de usuario y cualquier funcionalidad de e‑commerce futura.', false, 5000.00, 10000.00, 'USD', 'remoto', NULL, NULL, 'finalizado', NULL, '2026-06-24 00:00:00+00', '2026-07-04 00:00:00+00', 0, true, '2026-06-24 03:46:14.070037+00', '2026-06-24 04:38:27.888482+00', true),
	('4666d496-5ce0-4eac-8454-d6509cd2d138', 'fb546260-2e90-4954-944c-594b35461017', 'f7b10e42-2bb6-4068-b663-1ab4ec1993cd', 'necesito un sistema de inventario para mi tienda de ropa', 'Problema y contexto: La tienda de ropa en San José gestiona su inventario con hojas de cálculo y registros físicos, lo que genera errores de conteo, información desactualizada y demoras para identificar productos agotados, afectando el servicio al cliente y la eficiencia de la distribución.
Objetivo y alcance: El sistema debe automatizar la gestión del inventario permitiendo registrar, editar y eliminar productos, clasificarlos por categoría, talla, color y marca, mantener el stock en tiempo real, registrar entradas y salidas, generar alertas de reposición al alcanzar niveles mínimos, actualizar automáticamente el stock al registrar una venta, ofrecer consultas rápidas de disponibilidad y producir reportes de inventario, productos más vendidos y movimientos de stock, además de gestionar usuarios con roles de administrador y empleado.
Supuestos y exclusiones: Se asume que la tienda seguirá manejando las compras a través de procesos manuales y que el módulo de ventas ya está disponible para la integración de stock; quedan fuera la integración con proveedores externos, la facturación electrónica, cualquier aplicación móvil nativa, la gestión de envíos externos y la conexión con plataformas de comercio electrónico.', false, 1000.00, 2000.00, 'USD', 'hibrido', 'CR', 'CR-SJ', 'adjudicado', NULL, '2026-06-24 00:00:00+00', '2026-06-30 00:00:00+00', 0, true, '2026-06-24 07:09:40.869009+00', '2026-06-24 07:25:36.450887+00', true),
	('203f89e8-1673-437e-b915-383b650d188f', '257600b6-585a-4502-af52-f9973372cfd1', '159531c8-fefd-4fa5-b435-76bea788b6b7', 'Desarrollo de sitio web corporativo para mejorar presencia digital y captación de clientes', 'Problema y contexto: La empresa, dedicada a la venta y promoción de productos y servicios accesibles, confiables y de calidad, depende actualmente de redes sociales y otros medios externos para comunicar su oferta. Esta dispersión dificulta centralizar la información clave, presentar la propuesta de valor de forma estructurada y ofrecer una experiencia profesional a clientes actuales y potenciales. La falta de un canal propio debilita la imagen de marca y complica la gestión de consultas.
Objetivo y alcance: Desarrollar un sitio web corporativo moderno que centralice la información del negocio, comunique los valores y servicios de manera clara y facilite la interacción mediante formularios de contacto. El MVP incluirá una página de inicio, secciones informativas sobre la empresa, sus servicios y beneficios, una navegación intuitiva, formularios de solicitud y consulta, diseño responsive para computadoras, tablets y móviles, y optimización básica de carga. No se contemplan funcionalidades de comercio electrónico, gestión de usuarios ni integración con sistemas de pago.
Supuestos y exclusiones: Se asume que el cliente proveerá los textos, imágenes y la identidad visual; el proyecto se limitará a un sitio informativo con formularios de contacto y no incluirá e‑commerce, gestión de usuarios ni integración con plataformas externas. El plazo de 10 días y el presupuesto disponible restringen el alcance a un MVP estático con lógica de formulario en el cliente.', false, 700.00, 1800.00, 'USD', 'remoto', NULL, NULL, 'en_desarrollo', NULL, '2026-06-24 00:00:00+00', '2026-07-04 00:00:00+00', 0, true, '2026-06-24 05:20:02.467063+00', '2026-06-24 05:28:21.902247+00', true),
	('8c4b4bbc-2289-4e32-86d8-d662c2b26347', 'd66e446f-94b7-47d6-9728-1ec09601673b', '159531c8-fefd-4fa5-b435-76bea788b6b7', 'Aplicación móvil de pedidos de comida para restaurantes locales', 'Problema y contexto: El negocio consiste en una plataforma de pedidos de comida similar a PedidosYa, dirigida a consumidores de restaurantes locales que buscan aumentar sus ventas. Actualmente los restaurantes no cuentan con una herramienta digital que permita a los clientes buscar, seleccionar y pagar pedidos de forma rápida, lo que limita su alcance y sus ingresos. El proyecto se desarrollará con un presupuesto entre 200 y 1000 unidades monetarias, con un plazo de entrega de 8 días, utilizando la moneda CRC y considerando la ubicación en Saint Philip, Antigua y Barbuda.
Objetivo y alcance: El sistema debe permitir a los usuarios clientes buscar restaurantes, visualizar menús, armar un carrito de compra, pagar mediante una billetera digital, seguir el estado del pedido en tiempo real y recibir notificaciones. El alcance incluye una aplicación móvil desarrollada con Expo, un backend API que gestione usuarios, restaurantes, menús, pedidos y notificaciones, y una base de datos MySQL para almacenar la información transaccional. No se incluyen funcionalidades de gestión de inventario interno ni integración con sistemas de punto de venta externos.
Supuestos y exclusiones: Se asume que el cliente proporcionará la integración con la billetera digital y que los pagos se realizarán exclusivamente a través de este medio; los pagos en efectivo quedan fuera del alcance. No se desarrollará un portal administrativo web ni se implementarán reportes avanzados de ventas, ya que el empresario indicó que no los necesita en la fase inicial.', false, 200.00, 1000.00, 'CRC', 'hibrido', 'AG', 'AG-08', 'abierto', NULL, '2026-06-30 00:00:00+00', '2026-07-08 00:00:00+00', 0, true, '2026-06-30 03:55:50.596003+00', '2026-06-30 03:55:50.596003+00', true),
	('1d2c8b10-762a-43aa-9f5b-737a01962661', 'fb546260-2e90-4954-944c-594b35461017', '5a0f71eb-8d7b-4a2f-ad54-c6a99c68eb3d', 'necesito un sistema de inventario para mi tienda de ropa', 'Problema y contexto:
Actualmente la tienda de ropa gestiona su inventario de forma manual mediante hojas de cálculo y registros físicos, lo que genera errores en el conteo, falta de actualización en tiempo real del stock, pérdida de información y demoras para identificar productos agotados o disponibles. Estas limitaciones afectan el servicio al cliente, pues a veces se ofrecen productos que ya no están en existencia y no se detecta a tiempo la necesidad de reabastecimiento, además de dificultar la organización y el control de entradas y salidas de mercancía.
Objetivo y alcance:
El sistema tiene como objetivo automatizar la gestión del inventario para mejorar el control de los productos, optimizar los procesos operativos y brindar un mejor servicio al cliente. El software permitirá registrar, editar y eliminar productos, clasificarlos por categoría, talla, color y marca, y mantener el stock actualizado en tiempo real. También incluirá el registro de entradas y salidas de inventario, generación de alertas automáticas cuando el nivel de stock alcance el mínimo definido, y la actualización automática de existencias mediante la integración con el módulo de ventas. Los usuarios podrán consultar rápidamente la disponibilidad de productos y generar reportes de inventario, de los productos más vendidos y de los movimientos de stock. La gestión de usuarios contemplará roles de administrador y empleado con diferentes niveles de acceso.
Supuestos y exclusiones:
Se asume que el proyecto se desarrollará como una aplicación web accesible mediante navegador, con un presupuesto de entre 1000 y 2000 USD y un plazo de entrega de cinco días, bajo una modalidad híbrida y en moneda USD. Se incluye la integración con el módulo de ventas interno, pero se excluye la integración con proveedores externos, la facturación electrónica, la aplicación móvil nativa, la gestión de envíos y logística externa, y la integración con plataformas de comercio electrónico.', false, 1000.00, 2000.00, 'USD', 'hibrido', 'CR', 'CR-SJ', 'abierto', NULL, '2026-06-24 00:00:00+00', '2026-06-29 00:00:00+00', 0, true, '2026-06-24 07:48:24.14167+00', '2026-06-24 07:48:24.14167+00', true),
	('593c9fd3-cb4e-48d1-aef3-122920b0600d', 'fb546260-2e90-4954-944c-594b35461017', '5a0f71eb-8d7b-4a2f-ad54-c6a99c68eb3d', 'necesito un sistema de inventario para mi tienda de ropa', 'Problema y contexto: La tienda de ropa ubicada en San José, Costa Rica, no cuenta con una herramienta centralizada para consultar el stock, lo que retrasa la atención al cliente. Actualmente los empleados y el jefe deben buscar en listas físicas o en hojas de cálculo, lo que es lento y propenso a errores. Necesitan una forma rápida de ver la ropa disponible.
Objetivo y alcance: El sistema debe permitir a empleados y al jefe acceder a una página web donde se visualice el inventario de ropa y puedan buscar rápidamente por categoría, talla, color u otras características. La página mostrará una tabla o tarjetas con la información del producto (nombre, referencia, talla, color, cantidad) y ofrecerá un campo de búsqueda y filtros básicos. No incluirá gestión de pagos, historial de ventas ni edición del stock; solo visualización y búsqueda. Se entregará un MVP funcional en 6 días.
Supuestos y exclusiones: Se asume que el inventario será cargado inicialmente en una base de datos proporcionada por el cliente y que no se requerirá integración con sistemas de punto de venta; los pagos y el historial de ventas quedan fuera del alcance.', false, 1000.00, 2500.00, 'USD', 'presencial', 'CR', 'CR-SJ', 'adjudicado', NULL, '2026-06-24 00:00:00+00', '2026-06-30 00:00:00+00', 0, true, '2026-06-24 06:12:14.648956+00', '2026-06-24 07:49:47.874852+00', true);


