	('1fddf34b-70d1-4c1d-8947-da868e5dc732', 'd66e446f-94b7-47d6-9728-1ec09601673b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'abandonada', NULL, '2026-06-14 03:37:32.297889+00', '2026-06-15 20:48:17.881+00', NULL),
